"""Generators for `FUZZ-06` and `FUZZ-07`, plus the one reference model worth having.

Test plan §6.7 states each case's generator in its own **Generator / corpus** column, and that
column is a contract on this file as much as the invariant column is on the tests:

* `FUZZ-06` — *"Generated criterion graphs up to 30 nodes, cyclic and acyclic; generated work-ID
  input tuples"*
* `FUZZ-07` — *"Generated byte strings; generated interleavings of result and status writes"*

**Why the generators are asserted on directly, in green tests, today.** Both cases are written
ahead of every module they touch, so `require()` raises before the test body runs and the
strategies are never exercised. That leaves the generators as the untested half of a written-ahead
property test — and a degenerate strategy (only acyclic graphs, only one varying field, only
short byte strings) produces a case that passes **vacuously** the day someone removes the marker.
Nothing would say so: the property holds over a corpus that never contained a counterexample.

So `test_fuzz_generators.py` asserts the corpus has the shape §6.7 names, and those assertions run
now. They are the same role the positive control plays in `SEC-15`: proof that the machine can
speak before anyone relies on its silence.

One reference model lives here too — `topological_order`. That property is the one that is easy to
express *backwards*: asserting `order.index(a) > order.index(b)` when the edge means `a` must come
first passes against a reversed implementation and fails against a correct one. Kahn's algorithm
and a deliberately reversed variant make the expression checkable now. The other three properties
need no model: `sha256` injectivity and a dict round-trip are tautologies, and a crash-point
simulator for transaction atomicity would be a substantial program whose own correctness nothing
checks.
"""

from __future__ import annotations

import random
from dataclasses import dataclass
from typing import Sequence

from hypothesis import strategies as st

#: §6.7: *"criterion graphs up to 30 nodes"*. The ceiling is the plan's, not a tuning knob.
MAX_GRAPH_NODES = 30

#: `CT-ORCH-01`'s input set, verbatim and ordered. `FR-ORCH-01` computes `work_id` as a hash over
#: exactly these nine, and the design calls changing the set **breaking** — it invalidates every
#: stored result. Transcribed here rather than read from `aeh.orch`, so the generator asserts about
#: the design rather than agreeing with whatever the module happens to hash.
WORK_ID_FIELDS: tuple[str, ...] = (
    "run_id",
    "stage",
    "submission_id",
    "criterion_id",
    "judge_id",
    "package_version_id",
    "panel_config",
    "prompt_template_version",
    "extractor_version",
)

#: The stages a work unit can be enumerated for (design §3.9's `Stage`).
STAGES: tuple[str, ...] = ("extract", "judge", "synthesize", "deterministic", "integrity")


@dataclass(frozen=True)
class CriterionGraph:
    """A criterion dependency graph, as `FR-PKG-05` sees one: nodes plus directed edges.

    `edges` are `(before, after)` — `before` must be extracted before `after`, which is the
    direction `topological_order` has to satisfy. Stated once, here, because getting it backwards
    is the failure mode the reference model exists to catch.
    """

    nodes: tuple[str, ...]
    edges: tuple[tuple[str, str], ...]

    @property
    def is_cyclic(self) -> bool:
        return topological_order(self) is None


def topological_order(graph: CriterionGraph) -> list[str] | None:
    """Kahn's algorithm. `None` when the graph is cyclic.

    The **reference model**, used to prove the property expression in `FUZZ-06` is the right way
    round before any implementation exists. Not a substitute for `PackageCatalog.topological_order`
    — it is what the assertion is calibrated against.
    """
    incoming = {node: 0 for node in graph.nodes}
    outgoing: dict[str, list[str]] = {node: [] for node in graph.nodes}
    for before, after in graph.edges:
        outgoing[before].append(after)
        incoming[after] += 1

    ready = sorted(node for node, count in incoming.items() if count == 0)
    order: list[str] = []
    while ready:
        node = ready.pop(0)
        order.append(node)
        for successor in outgoing[node]:
            incoming[successor] -= 1
            if incoming[successor] == 0:
                ready.append(successor)
        ready.sort()

    return order if len(order) == len(graph.nodes) else None


def reversed_topological_order(graph: CriterionGraph) -> list[str] | None:
    """The **negative control**: a plausible off-by-direction implementation.

    Someone who reads `(before, after)` as "after depends on before, so emit `after` first" writes
    this. It is a legal ordering of the reversed graph and satisfies no edge of the real one, and
    a property asserted in the wrong direction cannot tell the two apart.
    """
    order = topological_order(
        CriterionGraph(nodes=graph.nodes, edges=tuple((b, a) for a, b in graph.edges))
    )
    return order


def satisfies_every_edge(order: Sequence[str], graph: CriterionGraph) -> bool:
    """`FUZZ-06`'s stated invariant: *"`topological_order` always satisfies every edge"*."""
    position = {node: index for index, node in enumerate(order)}
    if set(position) != set(graph.nodes):
        return False
    return all(position[before] < position[after] for before, after in graph.edges)


# --- strategies --------------------------------------------------------------------------------


#: The most edges a generated graph carries. At 30 nodes there are 435 forward-pointing pairs, and
#: drawing a boolean for each made one 200-graph corpus cost ~87,000 draws — slow enough that
#: hypothesis reported a health-check failure before the assertions ran. Edges are sampled from the
#: legal pairs instead, which is a handful of draws and produces the same shapes.
MAX_GRAPH_EDGES = 40


def _forward_pairs(count: int) -> list[tuple[int, int]]:
    """Every `(earlier, later)` index pair. Edges drawn from here point forward, so a graph built
    from them is acyclic by construction — a `filter` on cyclicity would discard most draws at 30
    nodes and shrink to something unreadable."""
    return [(earlier, later) for later in range(1, count) for earlier in range(later)]


@st.composite
def acyclic_graphs(draw, max_nodes: int = MAX_GRAPH_NODES) -> CriterionGraph:
    """A DAG: nodes in a fixed order, every edge pointing forward."""
    count = draw(st.integers(min_value=1, max_value=max_nodes))
    nodes = tuple(f"c{index:02d}" for index in range(count))
    pairs = _forward_pairs(count)
    chosen: list[tuple[int, int]] = []
    if pairs:
        chosen = draw(
            st.lists(
                st.sampled_from(pairs),
                max_size=min(len(pairs), MAX_GRAPH_EDGES),
                unique=True,
            )
        )
    return CriterionGraph(
        nodes=nodes, edges=tuple((nodes[a], nodes[b]) for a, b in chosen)
    )


@st.composite
def cyclic_graphs(draw, max_nodes: int = MAX_GRAPH_NODES) -> CriterionGraph:
    """A graph guaranteed to contain at least one cycle.

    Built by taking a DAG and adding one back-edge, so the cycle sits inside a realistic graph
    rather than being a two-node loop every time — `FR-PKG-05` rejects a write that *would make*
    the graph cyclic, and the interesting case is the edge that closes a long path.
    """
    count = draw(st.integers(min_value=2, max_value=max_nodes))
    nodes = tuple(f"c{index:02d}" for index in range(count))
    pairs = _forward_pairs(count)
    chosen = draw(
        st.lists(st.sampled_from(pairs), max_size=min(len(pairs), MAX_GRAPH_EDGES), unique=True)
    )
    edges = [(nodes[a], nodes[b]) for a, b in chosen]

    # The back-edge, plus the forward edge it closes over, so the cycle sits inside a real path
    # rather than being the same two-node loop every time.
    end = draw(st.integers(min_value=1, max_value=count - 1))
    start = draw(st.integers(min_value=0, max_value=end - 1))
    if (nodes[start], nodes[end]) not in edges:
        edges.append((nodes[start], nodes[end]))
    edges.append((nodes[end], nodes[start]))
    return CriterionGraph(nodes=nodes, edges=tuple(edges))


def criterion_graphs(max_nodes: int = MAX_GRAPH_NODES):
    """Both kinds, as §6.7 asks — *"cyclic and acyclic"*."""
    return st.one_of(acyclic_graphs(max_nodes), cyclic_graphs(max_nodes))


#: Field values kept to a small pool per field, deliberately.
#:
#: `FUZZ-06`'s invariant is *"distinct input tuples always yield distinct `work_id`s"*, so the
#: corpus has to contain tuples that differ in **one** field and agree in the other eight — which
#: is what catches an implementation that drops a field from the hash. Drawing free-form text per
#: field makes every tuple differ everywhere and tests nothing but sha256.
_FIELD_POOL: dict[str, tuple[str, ...]] = {
    "run_id": ("run-a", "run-b"),
    "stage": STAGES[:2],
    "submission_id": ("sub-1", "sub-2"),
    "criterion_id": ("crit-1", "crit-2"),
    "judge_id": ("judge-1", "judge-2"),
    "package_version_id": ("pkg-v1", "pkg-v2"),
    "panel_config": ("pbr:aaaa", "pbr:bbbb"),
    "prompt_template_version": ("tmpl-v1", "tmpl-v2"),
    "extractor_version": ("extract-v1", "extract-v2"),
}


@st.composite
def work_id_inputs(draw) -> dict[str, str]:
    """One `work_id` input tuple, as a mapping keyed by `CT-ORCH-01`'s field names."""
    return {field: draw(st.sampled_from(_FIELD_POOL[field])) for field in WORK_ID_FIELDS}


@st.composite
def work_id_input_pairs(draw) -> tuple[dict[str, str], dict[str, str], str]:
    """Two tuples differing in **exactly one** field, plus the name of that field.

    This is the shape the invariant needs. A pair differing everywhere proves nothing about any
    individual input; a pair differing in `extractor_version` alone proves that input reaches the
    hash, and `CT-ORCH-01` says every one of the nine is contract.
    """
    base = draw(work_id_inputs())
    field = draw(st.sampled_from(WORK_ID_FIELDS))
    alternatives = [v for v in _FIELD_POOL[field] if v != base[field]]
    other = dict(base)
    other[field] = draw(st.sampled_from(alternatives))
    return base, other, field


def blob_payloads():
    """§6.7: *"Generated byte strings"*.

    `min_size=0` matters — an empty blob is a legal input to `put()` and the boundary where a
    content-addressed store built on "hash the bytes, skip if falsy" goes wrong.
    """
    return st.binary(min_size=0, max_size=4096)


#: The two writes `FR-STORE-04` requires in one transaction: *"a work unit's result and its ledger
#: status transition"*.
WRITE_KINDS: tuple[str, ...] = ("result", "status")


def write_interleavings():
    """§6.7: *"generated interleavings of result and status writes"*.

    Permutations of the two writes across several work units, so the corpus contains the ordering
    a naive implementation gets wrong — a status transition committed before its result, which is
    the interleaving that leaves a ledger claiming done for a unit with nothing stored.
    """
    return st.lists(
        st.tuples(st.integers(min_value=0, max_value=4), st.sampled_from(WRITE_KINDS)),
        min_size=2,
        max_size=10,
    )


# --- deterministic samplers --------------------------------------------------------------------
#
# The same construction as the strategies above, driven by a seeded `random.Random` instead of a
# hypothesis draw.
#
# **Why both exist, and why the self-tests use these.** Asserting "the corpus contains cyclic and
# acyclic graphs" needs a whole corpus, and the obvious way to get one —
# `@given(st.lists(criterion_graphs(), min_size=120, max_size=120))` — does the opposite of what it
# looks like. Hypothesis *shrinks* toward minimal values, so the single drawn list is the simplest
# one the strategy admits: 120 one-node graphs, 120 identical tuples, 120 empty byte strings. That
# is precisely the degenerate corpus these assertions exist to reject, handed over by the tool
# meant to prevent it. Measured: all five corpus assertions failed, in 125 seconds.
#
# §6.7's seed policy for both cases is **"Fixed seed set"**, so a seeded sampler is not a
# workaround — it is what the plan asks for. The strategies stay because the fuzz cases need
# shrinking to report a readable counterexample; the samplers are how the corpus is characterized.


def sample_criterion_graph(rng: random.Random, max_nodes: int = MAX_GRAPH_NODES) -> CriterionGraph:
    """One graph, cyclic or acyclic, from `rng`."""
    cyclic = rng.random() < 0.5
    count = rng.randint(2 if cyclic else 1, max_nodes)
    nodes = tuple(f"c{index:02d}" for index in range(count))
    pairs = _forward_pairs(count)
    chosen = rng.sample(pairs, k=min(len(pairs), rng.randint(0, MAX_GRAPH_EDGES)))
    edges = [(nodes[a], nodes[b]) for a, b in chosen]

    if cyclic:
        end = rng.randint(1, count - 1)
        start = rng.randint(0, end - 1)
        if (nodes[start], nodes[end]) not in edges:
            edges.append((nodes[start], nodes[end]))
        edges.append((nodes[end], nodes[start]))
    return CriterionGraph(nodes=nodes, edges=tuple(edges))


def sample_work_id_pair(rng: random.Random) -> tuple[dict[str, str], dict[str, str], str]:
    """Two `work_id` input tuples differing in exactly one field, plus that field's name."""
    base = {field: rng.choice(_FIELD_POOL[field]) for field in WORK_ID_FIELDS}
    field = rng.choice(WORK_ID_FIELDS)
    other = dict(base)
    other[field] = rng.choice([v for v in _FIELD_POOL[field] if v != base[field]])
    return base, other, field


def sample_blob_payload(rng: random.Random) -> bytes:
    """One byte string, reaching the boundaries a content-addressed store gets wrong."""
    size = rng.choice([0, 0, 1, rng.randint(1, 64), rng.randint(64, 1024), rng.randint(512, 4096)])
    return bytes(rng.randrange(256) for _ in range(size))


def sample_write_interleaving(rng: random.Random) -> list[tuple[int, str]]:
    """One interleaving of result and status writes across a few work units."""
    length = rng.randint(2, 10)
    return [(rng.randint(0, 4), rng.choice(WRITE_KINDS)) for _ in range(length)]
